<?php
declare(strict_types=1);namespace Joomleague\Component\Joomleague\Site\Model;defined('_JEXEC')or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Model\BaseDatabaseModel;use Joomla\Database\DatabaseInterface;use Joomleague\Component\Joomleague\Domain\Service\PersonnelReader;
final class PersonnelModel extends BaseDatabaseModel{protected function populateState($ordering=null,$direction=null):void{$this->setState('project_id',Factory::getApplication()->getInput()->getInt('project_id',0));}/** @return array<string,mixed> */public function getPersonnel():array{$app=Factory::getApplication();$app->bootComponent('com_joomleague');$d=(new PersonnelReader(Factory::getContainer()->get(DatabaseInterface::class)))->forProject((int)$this->getState('project_id'),$app->getIdentity()->getAuthorisedViewLevels());if(isset($d['error']))$d['error']=$d['error']==='project_required'?'COM_JOOMLEAGUE_PERSONNEL_NO_PROJECT':'COM_JOOMLEAGUE_PERSONNEL_UNAVAILABLE';return$d;}}
